 @SuppressWarnings("unchecked") private Map<String,Object> proposed(Item item,Map<String,Object> statement,Map<String,Object> graph){
  require(item!=null&&item.rowId()!=null&&Set.of("REGISTER_CASH","LINK_SOURCE","COMPLETE_TRANSFER","COMPLETE_BOOKED_TRANSFER","SET_MEANING","REGISTER_TRANSFER_RAW","REPARSE_SOURCE","CORRECT_CHECKPOINT","UNDO_CHANGE","MAP_OVERDRAFT","CREATE_BANK_CHECKPOINT","REGISTER_CASH_WITH_REPARSE","LINK_BANK_CLOCK","LINK_AND_CLOSE_REVIEW","REGISTER_REPAIRED_TRANSFER_RAW","REPAIR_TRANSFER_ENDPOINT","REGISTER_BANK_INTEREST").contains(Objects.toString(item.action(),"")),"INVALID_RECON_ACTION");var r=row(item.rowId());require(r.get("statement_id").equals(statement.get("id")),"ROW_OUTSIDE_EXACT_RUN");verified(statement);var c=candidate(r,graph);var effects=new LinkedHashMap<String,BigDecimal>();String own=r.get("account_id").toString();BigDecimal signed=amount(r.get("amount")).multiply(new BigDecimal("OUT".equals(r.get("direction"))?-1:1));
  switch(item.action()){
   case "REPAIR_TRANSFER_ENDPOINT"->{var t=repairEndpoint(item,r);effects.put(own,signed);UUID old="OUT".equals(r.get("direction"))?t.fromAccountId():t.toAccountId();if(old!=null)effects.put(old.toString(),signed.negate());}

   case "REGISTER_REPAIRED_TRANSFER_RAW"->{reparse(item,r,false);require(item.partnerId()!=null&&item.otherAccountId()!=null&&!item.otherAccountId().equals(r.get("account_id"))&&((List<?>)c.get("matches")).isEmpty(),"EXACT_REPAIRED_TRANSFER_ENDPOINTS_REQUIRED");var partner=money.attempts(item.partnerId());require(!partner.isEmpty(),"PARTNER_SOURCE_REQUIRED");var pc=partner.getLast().candidate();require(pc!=null&&pc.parseStatus()==MoneyTypes.ParseStatus.PARSED&&MoneyOrdinaryAdmission.domestic(pc)&&pc.amount().compareTo(amount(r.get("amount")))==0&&!pc.direction().name().equals(r.get("direction"))&&rowNear(r,pc.occurredAt()),"PARTNER_TRANSFER_CASH_MISMATCH");var resolved=new MoneyAccountResolver().resolve(money.accounts(),pc.provider(),pc.direction()==MoneyTypes.Direction.OUT?pc.sourceAccountHint():pc.destinationAccountHint());require(resolved.resolved()&&item.otherAccountId().equals(resolved.account().id())&&!resolved.account().archived(),"PARTNER_ACCOUNT_MUST_BE_SOURCE_PROVED");require(db.queryForObject("select count(*) from money_transaction_sources where user_id=? and raw_event_id in (?,?)",Long.class,owner(),item.rawId(),item.partnerId())==0,"TRANSFER_SOURCE_ALREADY_POSTED");effects.put(own,signed);effects.put(item.otherAccountId().toString(),signed.negate());}

   case "LINK_BANK_CLOCK"->{var t=money.transaction(item.transactionId());MoneyMeaningService.version(t.version(),item.expectedVersion());require("SECOND".equals(r.get("time_precision"))&&!t.excluded()&&t.mergedInto()==null&&t.amount().compareTo(amount(r.get("amount")))==0&&r.get("account_id").equals("OUT".equals(r.get("direction"))?t.fromAccountId():t.toAccountId())&&t.occurredAt().atZone(ZoneId.of("Asia/Seoul")).toLocalDate().equals(instant(r.get("occurred_at")).atZone(ZoneId.of("Asia/Seoul")).toLocalDate()),"BANK_CLOCK_ACCOUNT_CASH_DATE_MISMATCH");require(merchant(r.get("description"),t.counterpartyText())||r.get("description").toString().contains("이자")&&Objects.toString(t.counterpartyText(),"").contains("이자"),"BANK_CLOCK_REQUIRES_INDEPENDENT_MERCHANT_EVIDENCE");require(((List<Map<String,Object>>)graph.get("facts")).stream().filter(f->!Boolean.TRUE.equals(f.get("excluded"))&&f.get("merged_into")==null&&amount(f.get("amount")).compareTo(t.amount())==0&&r.get("account_id").equals(f.get("OUT".equals(r.get("direction"))?"from_account_id":"to_account_id"))&&instant(f.get("occurred_at")).atZone(ZoneId.of("Asia/Seoul")).toLocalDate().equals(t.occurredAt().atZone(ZoneId.of("Asia/Seoul")).toLocalDate())).count()==1,"BANK_CLOCK_AMBIGUOUS_CANONICAL_CASH");effects.put(own,BigDecimal.ZERO);}

   case "REGISTER_CASH_WITH_REPARSE","REGISTER_BANK_INTEREST"->{if(item.action().equals("REGISTER_BANK_INTEREST")){require(r.get("description").toString().contains("이자")&&"OUT".equals(r.get("direction"))&&item.loanId()!=null&&item.principal()!=null&&item.principal().signum()==0&&item.interest()!=null&&item.interest().compareTo(amount(r.get("amount")))==0&&item.fee()!=null&&item.fee().signum()==0,"EXACT_BANK_INTEREST_ONLY_ALLOCATION_REQUIRED");var loan=new MoneyWebService(db,users,money,product,json).loan(item.loanId());MoneyMeaningService.version(loan.version(),item.loanVersion());}bankSource(item,r,false);require(amount(r.get("amount")).signum()>0&&((List<?>)c.get("matches")).isEmpty()&&db.queryForObject("select count(*) from money_transaction_sources where user_id=? and raw_event_id=?",Long.class,owner(),item.rawId())==0,"SOURCE_OR_BANK_CASH_ALREADY_REPRESENTED");require(!"DAY".equals(r.get("time_precision")),"DAY_ONLY_CASH_REQUIRES_CORROBORATING_BANK_TIME");effects.put(own,signed);}

   case "CREATE_BANK_CHECKPOINT"->{bankAnchor(item,r);effects.put(own,BigDecimal.ZERO);}

   case "MAP_OVERDRAFT"->{facility(item,r);effects.put(own,BigDecimal.ZERO);}
   case "UNDO_CHANGE"->{var prior=undoChange(item,r,false);effects.put(own,BigDecimal.ZERO);}

   case "REPARSE_SOURCE"->{MoneyService.text(item.reason(),500,true,"Bank-backed reprocess reason");reparse(item,r,false);effects.put(own,BigDecimal.ZERO);}
   case "CORRECT_CHECKPOINT"->{MoneyService.text(item.reason(),500,true,"Opening-balance timeline evidence");var cp=checkpoint(item,r);effects.put(own,BigDecimal.ZERO);}
   case "REGISTER_CASH"->{require(!"DAY".equals(r.get("time_precision")),"DAY_ONLY_CASH_REQUIRES_CORROBORATING_BANK_TIME");require(Boolean.TRUE.equals(c.get("newCashAllowed")),"EXISTING_OR_AMBIGUOUS_CASH_REQUIRES_SOURCE_LINK");require(item.transactionId()==null&&item.type()==null,"REGISTER_CASH_PRESERVES_UNRESOLVED_MEANING");effects.put(own,signed);}
   case "REGISTER_TRANSFER_RAW"->{require(Boolean.TRUE.equals(c.get("newCashAllowed")),"EXISTING_OR_AMBIGUOUS_CASH_REQUIRES_SOURCE_LINK");MoneyService.text(item.reason(),500,true,"Paired source evidence");require(item.rawId()!=null&&item.partnerId()!=null&&item.otherAccountId()!=null&&((List<Map<String,Object>>)c.get("notifications")).stream().anyMatch(n->item.rawId().equals(n.get("rawId"))&&n.get("transactionId")==null),"STATEMENT_CORROBORATED_PRIMARY_RAW_REQUIRED");require(!item.otherAccountId().equals(r.get("account_id")),"DISTINCT_TRANSFER_ACCOUNTS_REQUIRED");money.account(item.otherAccountId());effects.put(own,signed);effects.put(item.otherAccountId().toString(),signed.negate());}
   case "LINK_SOURCE","LINK_AND_CLOSE_REVIEW","SET_MEANING"->{require(item.transactionId()!=null&&item.transactionId().equals(c.get("selectedTransactionId")),"EXACT_MATCH_REQUIRED");var target=money.transaction(item.transactionId());MoneyMeaningService.version(target.version(),item.expectedVersion());if(item.action().equals("LINK_AND_CLOSE_REVIEW"))require(item.rawId()!=null&&((List<Map<String,Object>>)c.get("notifications")).stream().anyMatch(n->item.rawId().equals(n.get("rawId"))),"EXACT_SUPPORTING_RAW_REQUIRED");if(item.action().equals("SET_MEANING")){require(Set.of("EXPENSE","INCOME","REFUND","LOAN_PAYMENT").contains(Objects.toString(item.type(),"")),"USE_TRANSFER_ENDPOINT_COMMAND");MoneyService.text(item.reason(),500,true,"Evidence reason");}effects.put(own,BigDecimal.ZERO);}
   case "COMPLETE_BOOKED_TRANSFER"->{
    bookedTransfer(item,r,c);
    effects.put(own,BigDecimal.ZERO);
    effects.put(item.otherAccountId().toString(),signed.negate());
   }
   case "COMPLETE_TRANSFER"->{MoneyService.text(item.reason(),500,true,"Owner-confirmed endpoint evidence");var t=money.transaction(item.transactionId());MoneyMeaningService.version(t.version(),item.expectedVersion());boolean out="OUT".equals(r.get("direction"));require(!t.excluded()&&t.mergedInto()==null&&Set.of(MoneyTypes.TransactionType.INCOME,MoneyTypes.TransactionType.EXPENSE,MoneyTypes.TransactionType.TRANSFER).contains(t.type())&&t.amount().compareTo(amount(r.get("amount")))==0&&t.currency().equals(statement.get("currency"))&&rowNear(r,t.occurredAt()),"TRANSFER_EVIDENCE_MISMATCH");require(out?t.fromAccountId()==null&&t.toAccountId()!=null&&!t.toAccountId().equals(r.get("account_id")):t.toAccountId()==null&&t.fromAccountId()!=null&&!t.fromAccountId().equals(r.get("account_id")),"TRANSFER_ENDPOINT_ALREADY_PRESENT_OR_CONFLICT");require(Boolean.TRUE.equals(c.get("newCashAllowed")),"EXISTING_STATEMENT_SIDE_WOULD_DUPLICATE_TRANSFER");UUID other=out?t.toAccountId():t.fromAccountId();money.account(other);require(db.queryForObject("select count(*) from money_transactions where user_id=? and refund_of=? and not excluded",Long.class,owner(),t.id())==0,"REFUND_DEPENDENCY_BLOCKS_TRANSFER");effects.put(own,signed);effects.put(other.toString(),BigDecimal.ZERO);}
   default->throw new InvalidRequestException("UNSUPPORTED_ACTION");
  }
  return Map.of("item",item,"cashImpact",effects,"evidence",c,"meaningPolicy",item.action().equals("REGISTER_CASH")?"UNRESOLVED_CASH_ONLY":"EXACT_OWNER_APPROVED_ACTION");
 }
 private boolean receiptMatches(MoneyTypes.MoneyTransaction current,tools.jackson.databind.JsonNode after){
  var previous=json.convertValue(after,Map.class);previous.putIfAbsent("occurrencePrecision","SECOND");previous.putIfAbsent("transferDestinationStatus",null);
  return json.readTree(json.writeValueAsString(current)).equals(json.readTree(json.writeValueAsString(previous)));
 }
