    db.update("update money_transactions set type=?,meaning_state=?,from_account_id=?,to_account_id=?,version=version+1 where user_id=? and id=?",
        old.type().name(),old.meaningState(),old.fromAccountId(),old.toAccountId(),owner(),subject);
